{
  "hechos": [
    {
      "id": "H1",
      "texto": "Regirá un toque de queda en Puerto Celeste entre las 10 de la noche y las 5 de la mañana.",
      "paginas": ["P1", "P2", "P3", "P4"]
    },
    {
      "id": "H2",
      "texto": "Los taxistas no saben si podrán trabajar en el turno de la noche.",
      "paginas": ["P1"]
    },
    {
      "id": "H3",
      "texto": "Andrés Quintero, líder comunal del barrio Los Almendros, contó a Crónica Andina que los vecinos organizaron rondas antes de que saliera el decreto.",
      "paginas": ["P2"]
    },
    {
      "id": "H4",
      "texto": "El toque de queda regirá por quince días.",
      "paginas": ["P1", "P2", "P3", "P4"]
    },
    {
      "id": "H5",
      "texto": "Incumplir la restricción puede costar una multa de hasta 800.000 pesos.",
      "paginas": ["P1", "P2", "P3", "P4"]
    },
    {
      "id": "H6",
      "texto": "En el barrio La Pradera, la junta de acción comunal registró 64 denuncias de robo en el último mes.",
      "paginas": ["P1"]
    },
    {
      "id": "H7",
      "texto": "Gloria Cárdenas, líder comunal del barrio El Prado, contó a Diario Sabana que en su cuadra robaron tres casas en una semana.",
      "paginas": ["P3"]
    },
    {
      "id": "H8",
      "texto": "En el barrio Villa Nueva, la junta de acción comunal registró 47 denuncias de robo en el último mes.",
      "paginas": ["P3"]
    },
    {
      "id": "H9",
      "texto": "Sandra Ospina, docente del barrio San José, contó a Noticias Altiplano que los restaurantes del malecón cerraron más temprano.",
      "paginas": ["P4"]
    },
    {
      "id": "H10",
      "texto": "En el barrio El Carmen, la junta de acción comunal registró 448 denuncias de robo en el último mes.",
      "paginas": ["P2"]
    },
    {
      "id": "H11",
      "texto": "En el barrio El Bosque, la junta de acción comunal registró 234 denuncias de robo en el último mes.",
      "paginas": ["P4"]
    }
  ]
}
